import * as React from 'react';

import { loadHighlighter } from '@/registry/default/lib/highlighter';

export function useHighlightedCode(value: string, language: string) {
  // A trailing newline would render as an extra empty line.
  const code = value.endsWith('\n') ? value.slice(0, -1) : value;
  const [loaded, setLoaded] = React.useState<{
    language: string;
    highlighter: Awaited<ReturnType<typeof loadHighlighter>>;
  } | null>(null);
  const highlighter = loaded?.language === language ? loaded.highlighter : null;

  React.useEffect(() => {
    let cancelled = false;

    loadHighlighter(language)
      .then((loadedHighlighter) => {
        if (!cancelled) {
          setLoaded({ language, highlighter: loadedHighlighter });
        }
      })
      .catch(() => {});

    return () => {
      cancelled = true;
    };
  }, [language]);

  // The complete lines, highlighted. While the code streams, only the new
  // lines are tokenized, starting from the grammar state of the last one.
  const [completeLines, setCompleteLines] = React.useState<{
    highlighter: typeof highlighter;
    text: string;
    lines: React.ReactNode[];
    state?: Parameters<NonNullable<typeof highlighter>['highlight']>[1];
  }>({ highlighter: null, text: '', lines: [] });

  let nextCompleteLines = completeLines;

  if (
    nextCompleteLines.highlighter !== highlighter ||
    !code.startsWith(nextCompleteLines.text)
  ) {
    nextCompleteLines = { highlighter, text: '', lines: [] };
  }

  const end = code.lastIndexOf('\n') + 1;

  if (highlighter && end > nextCompleteLines.text.length) {
    const result = highlighter.highlight(
      code.slice(nextCompleteLines.text.length, end - 1),
      nextCompleteLines.state
    );

    nextCompleteLines = {
      highlighter,
      text: code.slice(0, end),
      lines: [...nextCompleteLines.lines, ...result.lines],
      state: result.state,
    };
  }

  if (nextCompleteLines !== completeLines) {
    setCompleteLines(nextCompleteLines);
  }

  // The last line is still being written, so it is tokenized on every render.
  const tail = code.slice(end);

  return React.useMemo(() => {
    if (!highlighter) {
      return code.split('\n');
    }

    return [
      ...nextCompleteLines.lines,
      highlighter.highlight(tail, nextCompleteLines.state).lines[0],
    ];
  }, [code, highlighter, nextCompleteLines, tail]);
}

import {
  createHighlighterCore,
  getTokenStyleObject,
  type GrammarState,
  type HighlighterCore,
  type LanguageRegistration,
} from 'shiki/core';
import { createJavaScriptRegexEngine } from 'shiki/engine/javascript';

import { cssVarsTheme } from '@/registry/default/ui/code/code-themes';
import numscriptGrammar from '@/registry/default/ui/code/numscript.tmLanguage.json';

// The shadcn highlighter for CodeBlock, with the Formance code theme: every
// token color is a `--shiki-token-*` variable from code-themes.css, so light
// and dark mode come from the stylesheet, as in CodeSnippet.

const numscript: LanguageRegistration = { ...numscriptGrammar, repository: {} };

// Add the languages you need. Each one loads the first time it is used.
const languages = {
  bash: () => import('shiki/langs/shellscript.mjs'),
  css: () => import('shiki/langs/css.mjs'),
  go: () => import('shiki/langs/go.mjs'),
  html: () => import('shiki/langs/html.mjs'),
  javascript: () => import('shiki/langs/javascript.mjs'),
  json: () => import('shiki/langs/json.mjs'),
  markdown: () => import('shiki/langs/markdown.mjs'),
  numscript: () =>
    Promise.resolve({
      default: [numscript],
    }),
  python: () => import('shiki/langs/python.mjs'),
  sql: () => import('shiki/langs/sql.mjs'),
  toml: () => import('shiki/langs/toml.mjs'),
  tsx: () => import('shiki/langs/tsx.mjs'),
  typescript: () => import('shiki/langs/typescript.mjs'),
  yaml: () => import('shiki/langs/yaml.mjs'),
};

const aliases: Record<string, keyof typeof languages> = {
  js: 'javascript',
  jsx: 'tsx',
  md: 'markdown',
  py: 'python',
  sh: 'bash',
  shell: 'bash',
  shellscript: 'bash',
  ts: 'typescript',
  yml: 'yaml',
  zsh: 'bash',
};

let highlighter: Promise<HighlighterCore> | undefined;

function getHighlighter() {
  highlighter ??= createHighlighterCore({
    themes: [cssVarsTheme],
    langs: [],
    engine: createJavaScriptRegexEngine({ forgiving: true }),
  });

  return highlighter;
}

function getLanguage(language: string) {
  const name = language.toLowerCase();

  if (name === 'ansi') {
    return name;
  }

  if (name in languages) {
    return name as keyof typeof languages;
  }

  return aliases[name] ?? null;
}

// Loads a language and returns a highlighter for it, or null for a language
// that is not listed.
export async function loadHighlighter(language: string) {
  const lang = getLanguage(language);

  if (!lang) {
    return null;
  }

  const shiki = await getHighlighter();

  if (lang !== 'ansi' && !shiki.getLoadedLanguages().includes(lang)) {
    await shiki.loadLanguage(languages[lang]);
  }

  return {
    // Returns one React node per line, and the grammar state after the last
    // line. Pass that state back to continue where the code left off.
    highlight(code: string, state?: GrammarState) {
      const tokenize = (text: string) =>
        shiki.codeToTokens(text, {
          lang,
          theme: cssVarsTheme.name ?? 'formance-css-vars',
          grammarState: state,
        }).tokens;

      // ANSI has no grammar state, so each line is tokenized on its own and
      // gets the same colors whether it arrives in one piece or streams.
      const tokens =
        lang === 'ansi'
          ? code.split('\n').flatMap((line) => tokenize(line))
          : tokenize(code);

      return {
        lines: tokens.map((line) =>
          line.map((token, index) => {
            const style = getTokenStyleObject(token);

            return (
              <span
                key={index}
                style={{
                  color: style.color,
                  fontStyle: style['font-style'],
                  fontWeight: style['font-weight'],
                  textDecoration: style['text-decoration'],
                }}
              >
                {token.content}
              </span>
            );
          })
        ),
        state: shiki.getLastGrammarState(tokens),
      };
    },
  };
}

// Returns one React node per line, or null for a language that is not listed.
export async function highlightCode(code: string, language: string) {
  const highlighter = await loadHighlighter(language);

  return highlighter ? highlighter.highlight(code).lines : null;
}
